{"cards": [{"node_code": "N_6b3923e78568b9d1", "definition": "研究利用无线电波信号确定目标方位角的技术，涵盖测向原理、设备性能及在航海避碰、定位中的应用。", "boundary": "本节点聚焦于“测向”（Direction Finding），即确定相对方位。边界在于区分“测向”与“测距/定位”：若仅确定方向线，归入本节点；若结合多站信号确定具体坐标，归入无线电导航。若涉及测向仪内部电路设计，归入船舶工程。", "includes": ["无线电测向基本原理与误差分析", "船舶测向设备的使用与操作规范", "利用测向线进行单站或多站定位的方法"], "excludes": ["基于距离或时间差的无线电定位系统（归入无线电导航）", "测向设备的硬件制造与电路研发（归入船舶工程）"], "sibling_distinctions": [{"other_code": "N_c94a06d2ca6cc110", "rule": "本节点侧重确定“方向”（方位角），兄弟节点侧重确定“位置”（坐标），后者通常依赖测距或时间差。"}, {"other_code": "N_3349ff650fc050a9", "rule": "本节点主要处理无线电通信信号，兄弟节点侧重雷达回波信号在探测与导航中的应用。"}], "cross_boundary_rule": "若内容涉及利用测向数据辅助避碰或确定相对方位，主挂载本节点；若涉及利用测向线交汇确定船位，可关联无线电导航，但核心原理仍属测向。"}, {"node_code": "N_c94a06d2ca6cc110", "definition": "研究利用无线电波传播特性（如距离、时间差、相位）确定船舶位置的技术，涵盖各类无线电定位系统原理与应用。", "boundary": "本节点聚焦于“定位”（Positioning），即确定绝对或相对坐标。边界在于区分“定位”与“测向”：若核心是计算坐标，归入本节点；若仅获取方位，归入无线电测向。若涉及卫星导航（GPS/GNSS）在航海中的具体应用，归入本节点。", "includes": ["双曲线定位系统（如LORAN-C、DECCA）原理与应用", "卫星导航系统（GPS、北斗等）在航海中的使用", "雷达定位、激光测距等无线电/电磁波定位技术"], "excludes": ["仅涉及方位角确定的测向技术（归入无线电测向）", "导航设备的硬件结构与制造工艺（归入船舶工程）"], "sibling_distinctions": [{"other_code": "N_6b3923e78568b9d1", "rule": "本节点侧重确定“位置”（坐标），兄弟节点侧重确定“方向”（方位角）。"}, {"other_code": "N_1c157b30dc3e1b24", "rule": "本节点侧重提供位置信息源，兄弟节点侧重利用位置信息实现自动航路跟踪与控制。"}], "cross_boundary_rule": "若内容涉及卫星导航信号接收与解算，主挂载本节点；若涉及基于导航数据的自动舵控制逻辑，主挂载自动导航。"}, {"node_code": "N_1c157b30dc3e1b24", "definition": "研究利用计算机、传感器及控制算法实现船舶航路自动跟踪、操纵与监控的技术，涵盖自动舵、ECDIS及集成系统。", "boundary": "本节点聚焦于“自动化”与“控制”，即从感知到执行的闭环过程。边界在于区分“信息获取”（导航/通信）与“信息处理与控制”（自动导航）。若涉及自动舵原理、航路规划算法、ECDIS操作，归入本节点。", "includes": ["自动舵系统原理、操作及故障处理", "电子海图显示与信息系统（ECDIS）的应用", "船舶自动识别系统（AIS）及综合导航台（INT）集成技术"], "excludes": ["导航传感器（如GPS、雷达）的硬件制造（归入船舶工程）", "纯人工操舵技巧与经验（归入船舶驾驶基础）"], "sibling_distinctions": [{"other_code": "N_c94a06d2ca6cc110", "rule": "本节点侧重“控制与执行”（如何保持航向/航路），兄弟节点侧重“位置获取”（如何知道在哪里）。"}, {"other_code": "N_c7ef8217abf60b4a", "rule": "本节点侧重导航数据的自动化处理与控制，兄弟节点侧重语音、数据的人机或船岸通信。"}], "cross_boundary_rule": "若内容涉及自动舵如何根据GPS信号修正航向，主挂载本节点；若内容涉及GPS信号本身的接收原理，主挂载无线电导航。"}]}
